-- # Simple Lexer generated by alex
--
{-# LANGUAGE GHC2024 #-}

module Main 
    ( main
    ) where

import System.Environment
import Lexer.AlexSimple

main :: IO ()
main =  getArgs 
    >>= phi
    >>= mapM_ print . alexSimpleLexer
    where
        phi = \ case
            []  -> getContents
            a:_ -> readFile a
